import{_ as e,o as t,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"数据分析 Agent","description":"项目契约：实现能够理解指标、生成受限 SQL、执行只读查询并输出可追溯分析的数据 Agent。","frontmatter":{"title":"数据分析 Agent","description":"项目契约：实现能够理解指标、生成受限 SQL、执行只读查询并输出可追溯分析的数据 Agent。","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"py-agent/architecture/projects/data-analysis-agent.md","filePath":"py-agent/architecture/projects/data-analysis-agent.md","lastUpdated":null}'),r={name:"py-agent/architecture/projects/data-analysis-agent.md"};function l(o,a,s,c,d,h){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="数据分析-agent" tabindex="-1">数据分析 Agent <a class="header-anchor" href="#数据分析-agent" aria-label="Permalink to &quot;数据分析 Agent&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本项目类型为 <strong>受控数据 Agent</strong>。重点是让模型参与指标理解和查询规划，同时把数据库权限、SQL 校验、资源预算和结果解释留在确定性边界内。</p><h2 id="项目结果" tabindex="-1">项目结果 <a class="header-anchor" href="#项目结果" aria-label="Permalink to &quot;项目结果&quot;">​</a></h2><p>读者最终会得到一个分析 API：用户用自然语言询问业务指标，Agent 选择允许的数据集，生成并校验只读 SQL，执行查询后返回表格、图表描述、结论和完整查询证据。</p><h2 id="实现范围" tabindex="-1">实现范围 <a class="header-anchor" href="#实现范围" aria-label="Permalink to &quot;实现范围&quot;">​</a></h2><ul><li>指标目录定义业务口径、维度、时间粒度和允许的数据源；</li><li>LangChain 工具承载 Schema 检索、SQL 规划、查询执行和结果解释；</li><li>SQL 解析器拒绝写操作、跨 Schema 访问、无界扫描和危险函数；</li><li>PostgreSQL 只读角色、Statement Timeout 和行级策略形成数据库防线；</li><li>SQLAlchemy 管理连接、事务和结果类型；</li><li>查询、参数、行数、耗时和模型解释进入审计与 Trace；</li><li>测试覆盖口径歧义、非法 SQL、超时、空结果、租户隔离和大结果集。</li></ul><h2 id="验收基线" tabindex="-1">验收基线 <a class="header-anchor" href="#验收基线" aria-label="Permalink to &quot;验收基线&quot;">​</a></h2><p>项目必须证明模型无法通过工具执行写操作或读取未授权表，并能够复现每条结论对应的 SQL 和结果集。任意 Python 代码执行和自动修改数据库不属于项目范围。</p>',9)])])}const g=e(r,[["render",l]]);export{u as __pageData,g as default};
